const cache = new InMemoryCache({
  typePolicies: {
    Query: {
      fields: {
        user: {
          // Redirect to cached Profile query if available
          read(_, { args, cache }) {
            const profile = cache.readQuery({
              query: GET_PROFILE,
              variables: { id: args?.id },
            });
            if (profile) return profile.user;
            return undefined;
          },
        },
      },
    },
  },
});
